using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// Redirect all logging to stderr so it never corrupts the stdio JSON-RPC stream
builder.Logging.ClearProviders();
builder.Logging.AddConsole(opts => opts.LogToStandardErrorThreshold = LogLevel.Trace);

// Register HttpClient via DI
builder.Services.AddHttpClient("ExternalApi");

// Register the MCP server with stdio transport
builder.Services
    .AddMcpServer(options =>
    {
        options.ServerInfo = new() { Name = "MyMcpServer", Version = "1.0.0" };
    })
    .WithStdioServerTransport()
    .WithTools<ApiTools>()
    .WithPrompts<SummarizationPrompts>();

var app = builder.Build();
await app.RunAsync();

